def stable_toposort(graph):
    nodes = list(graph.keys())
    node_set = set(nodes)

    # Validate: all dependencies must be keys in the graph
    for node, deps in graph.items():
        for dep in deps:
            if dep not in node_set:
                raise ValueError(
                    f"Missing dependency: {dep!r} (required by {node!r})"
                )

    # Build in-degree (unmet dependency count) and reverse adjacency
    in_degree = {node: len(deps) for node, deps in graph.items()}
    dependents = {node: [] for node in nodes}
    for node, deps in graph.items():
        for dep in deps:
            dependents[dep].append(node)

    # Stable topological sort
    ready = set(node for node in nodes if in_degree[node] == 0)
    result = []

    while ready:
        # Pick the ready node that appears first in the original dict order
        for node in nodes:
            if node in ready:
                ready.remove(node)
                result.append(node)
                for dependent in dependents[node]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        ready.add(dependent)
                break

    if len(result) != len(nodes):
        remaining = set(nodes) - set(result)
        raise ValueError(f"Cycle detected involving nodes: {remaining}")

    return result
