def schema_drift(expected, actual):
    results = []

    def collect_leaves(d, prefix):
        leaves = []
        for k, v in d.items():
            path = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                leaves.extend(collect_leaves(v, path))
            else:
                leaves.append(path)
        return leaves

    def compare(exp, act, prefix):
        for key in exp:
            path = f"{prefix}.{key}" if prefix else key
            if key not in act:
                if isinstance(exp[key], dict):
                    for leaf in collect_leaves(exp[key], path):
                        results.append((leaf, "missing"))
                else:
                    results.append((path, "missing"))
            else:
                if isinstance(exp[key], dict) and isinstance(act[key], dict):
                    compare(exp[key], act[key], path)
                elif isinstance(exp[key], dict) or isinstance(act[key], dict):
                    results.append((path, "type_mismatch"))
                else:
                    if exp[key] != act[key]:
                        results.append((path, "type_mismatch"))

        for key in act:
            if key not in exp:
                path = f"{prefix}.{key}" if prefix else key
                if isinstance(act[key], dict):
                    for leaf in collect_leaves(act[key], path):
                        results.append((leaf, "extra"))
                else:
                    results.append((path, "extra"))

    compare(expected, actual, "")
    results.sort(key=lambda x: (x[0], x[1]))
    return results
