def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be a positive integer")

    batches = []
    current = []
    current_total = 0

    for item in items:
        row_count = item[1]
        if row_count > max_rows:
            if current:
                batches.append(current)
            current = [item]
            current_total = row_count
        elif current_total + row_count <= max_rows:
            current.append(item)
            current_total += row_count
        else:
            batches.append(current)
            current = [item]
            current_total = row_count

    if current:
        batches.append(current)

    return batches
